1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	type Store struct {
32		dir string
33	
34		mu     sync.Mutex
35		jobs   []*storedJob // 严格按作业号（即提交先后）排列
36		byID   map[uint64]*storedJob
37		idem   map[string]uint64 // submitter\x00requestID -> 作业号
38		nextID uint64
39		closed bool
40	
41		now func() time.Time
42	
43		runningID uint64
44		waitCh    chan struct{}
45		stopCh    chan struct{}
46		stopping  atomic.Bool
47		wg        sync.WaitGroup
48	
49		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
50		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
51		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
52		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
53	}
54	
55	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
56	//
57	// 恢复语义：
58	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
59	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
60	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
61	//   - 成功状态始终与完整归档同时可见。
62	func Open(dir string, opts ...Option) (*Store, error) {
63		if err := os.MkdirAll(dir, 0o700); err != nil {
64			return nil, err
65		}
66		jobs, maxID, err := loadDir(dir)
67		if err != nil {
68			return nil, err
69		}
70		s := &Store{
71			dir:    dir,
72			jobs:   jobs,
73			byID:   make(map[uint64]*storedJob),
74			idem:   make(map[string]uint64),
75			nextID: maxID + 1,
76			now:    wallClock{}.Now,
77			waitCh: make(chan struct{}, 1),
78			stopCh: make(chan struct{}),
79		}
80		for _, opt := range opts {
81			opt(s)
82		}
83		for _, j := range jobs {
84			s.byID[j.id] = j
85			if j.requestID != "" {
86				s.idem[s.idemKey(j.submitter, j.requestID)] = j.id
87			}
88		}
89		// 重建失败/取消作业对排队下游的阻断。
90		s.cascadeLocked()
91		s.wg.Add(1)
92		go s.worker()
93		return s, nil
94	}
95	
96	func (s *Store) idemKey(submitter, requestID string) string {
97		return submitter + "\x00" + requestID
98	}
99	
100	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
101	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
102	func (s *Store) Close() error {
103		s.mu.Lock()
104		if s.closed {
105			s.mu.Unlock()
106			return nil
107		}
108		s.closed = true
109		var running *storedJob
110		if s.runningID != 0 {
111			running = s.byID[s.runningID]
112		}
113		s.mu.Unlock()
114	
115		if s.stopping.CompareAndSwap(false, true) {
116			close(s.stopCh)
117		}
118		// 中止正在运行的计算。
119		if running != nil {
120			running.canceled.Store(true)
121		}
122		s.notify()
123		s.wg.Wait()
124		return nil
125	}
126	
127	// Submit 接受一次作业提交。
128	//
129	// 空序列返回 [ErrEmptySequence]；引用不存在的依赖返回
130	// [ErrDependencyNotFound]；同一提交人复用请求号但内容变化返回
131	// [ErrIdempotencyConflict]（同时返回原作业视图）——这些拒绝都不产生记录。
132	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
133	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
134		s.mu.Lock()
135		defer s.mu.Unlock()
136		if s.closed || s.stopping.Load() {
137			return nil, ErrStoreClosed
138		}
139		if len(req.Values) == 0 {
140			return nil, ErrEmptySequence
141		}
142		if req.HasDependency {
143			if s.byID[req.DependencyID] == nil {
144				return nil, fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, req.DependencyID)
145			}
146		}
147		if req.RequestID != "" {
148			key := s.idemKey(req.Submitter, req.RequestID)
149			if origID, ok := s.idem[key]; ok {
150				orig := s.byID[origID]
151				if sameContent(orig, &req) {
152					return s.viewLocked(orig), nil
153				}
154				return s.viewLocked(orig),
155					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d",
156						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID)
157			}
158		}
159	
160		now := s.now().UTC()
161		j := &storedJob{
162			id:            s.nextID,
163			submitter:     req.Submitter,
164			requestID:     req.RequestID,
165			seed:          req.Seed,
166			values:        append([]int64(nil), req.Values...),
167			hasDependency: req.HasDependency,
168			dependencyID:  req.DependencyID,
169			queuedAt:      now,
170			status:        StatusQueued,
171		}
172		// 先持久化，接受之后该提交即不可丢失。
173		if err := s.persist(j); err != nil {
174			return nil, err
175		}
176		s.nextID++
177		s.jobs = append(s.jobs, j)
178		s.byID[j.id] = j
179		if req.RequestID != "" {
180			s.idem[s.idemKey(req.Submitter, req.RequestID)] = j.id
181		}
182		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
183		s.cascadeLocked()
184		s.notifyLocked()
185		return s.viewLocked(j), nil
186	}
187	
188	// sameContent 判断两次提交的内容是否一致；整数次序不同即视为不同内容。
189	func sameContent(j *storedJob, req *SubmitRequest) bool {
190		if j.seed != req.Seed || j.hasDependency != req.HasDependency {
191			return false
192		}
193		if j.hasDependency && j.dependencyID != req.DependencyID {
194			return false
195		}
196		if len(j.values) != len(req.Values) {
197			return false
198		}
199		for i := range j.values {
200			if j.values[i] != req.Values[i] {
201				return false
202			}
203		}
204		return true
205	}
206	
207	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
208	func (s *Store) Get(id uint64) (*Job, error) {
209		s.mu.Lock()
210		defer s.mu.Unlock()
211		j := s.byID[id]
212		if j == nil {
213			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
214		}
215		return s.viewLocked(j), nil
216	}
217	
218	// Cancel 请求取消作业。
219	//
220	// 排队或运行中的作业都可以取消；取消一旦返回成功，该作业及依赖它的作业
221	// 都不会再产生成功归档。重复取消已取消的作业仍返回成功；对已成功或已
222	// 失败的作业取消返回 [ErrNotCancellable]，原结果保持不变。
223	func (s *Store) Cancel(id uint64) (*Job, error) {
224		s.mu.Lock()
225		defer s.mu.Unlock()
226		if s.closed {
227			return nil, ErrStoreClosed
228		}
229		j := s.byID[id]
230		if j == nil {
231			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
232		}
233		switch j.status {
234		case StatusCanceled:
235			return s.viewLocked(j), nil
236		case StatusSucceeded, StatusFailed:
237			return s.viewLocked(j),
238				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
239		}
240	
241		// queued / running：立刻把终态落盘，使“已确认的取消”不会因崩溃丢失。
242		now := s.now().UTC()
243		j.status = StatusCanceled
244		j.failureReason = ""
245		j.blockerID = 0
246		if j.finishedAt.IsZero() {
247			j.finishedAt = now
248		}
249		j.effectiveValues = nil
250		j.archive = nil
251		j.canceled.Store(true)
252		if err := s.persist(j); err != nil {
253			return nil, err
254		}
255		// 依赖它的等待者一并失败，且继续向更下游传播。
256		s.cascadeLocked()
257		s.notifyLocked()
258		return s.viewLocked(j), nil
259	}
260	
261	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
262	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
263	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
264		s.mu.Lock()
265		defer s.mu.Unlock()
266		if !start.IsZero() && !end.IsZero() && start.After(end) {
267			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
268				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
269		}
270		out := make([]*Job, 0)
271		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
272			if j.submitter != submitter {
273				continue
274			}
275			if !start.IsZero() && j.queuedAt.Before(start) {
276				continue
277			}
278			if !end.IsZero() && j.queuedAt.After(end) {
279				continue
280			}
281			out = append(out, s.viewLocked(j))
282		}
283		return out, nil
284	}
285	
286	// cascadeLocked 把“依赖已失败/取消”的排队作业标记为失败并递归传播。
287	//
288	// 依赖在提交时必须已存在，因此依赖作业号必然更小，按作业号升序单趟
289	// 扫描即可让阻断沿链条传播到最下游。
290	func (s *Store) cascadeLocked() {
291		for _, j := range s.jobs {
292			if j.status != StatusQueued || !j.hasDependency {
293				continue
294			}
295			dep := s.byID[j.dependencyID]
296			if dep == nil {
297				continue
298			}
299			if dep.status != StatusFailed && dep.status != StatusCanceled {
300				continue
301			}
302			root := dep.blockerID
303			if root == 0 {
304				root = dep.id
305			}
306			s.markFailedLocked(j, blockedReason(dep, root), root)
307		}
308	}
309	
310	func blockedReason(dep *storedJob, root uint64) string {
311		state := "失败"
312		if dep.status == StatusCanceled {
313			state = "被取消"
314		}
315		reason := fmt.Sprintf("依赖的作业 %d 已%s，阻断本作业继续计算", dep.id, state)
316		if dep.status == StatusFailed && dep.failureReason != "" {
317			reason += "（其失败原因：" + dep.failureReason + "）"
318		}
319		if root != dep.id {
320			reason += fmt.Sprintf("；阻断根因为作业 %d", root)
321		}
322		return reason
323	}
324	
325	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
326	// 等待依赖（依赖排队/运行中）的作业会被跳过，不挡住后面的作业。
327	func (s *Store) pickRunnableLocked() *storedJob {
328		for _, j := range s.jobs {
329			if j.status != StatusQueued {
330				continue
331			}
332			if !j.hasDependency {
333				return j
334			}
335			if dep := s.byID[j.dependencyID]; dep != nil && dep.status == StatusSucceeded {
336				return j
337			}
338		}
339		return nil
340	}
341	
342	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
343	func (s *Store) notifyLocked() {
344		select {
345		case s.waitCh <- struct{}{}:
346		default:
347		}
348	}
349	
350	// notify 在不持锁时唤醒 worker。
351	func (s *Store) notify() {
352		s.mu.Lock()
353		s.notifyLocked()
354		s.mu.Unlock()
355	}
356	
357	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
358	func (s *Store) persistRetry(j *storedJob, attempts int) error {
359		var err error
360		for i := 0; i < attempts; i++ {
361			if err = s.persist(j); err == nil {
362				return nil
363			}
364		}
365		return err
366	}
367	
368	// worker 是本地唯一的计算执行体。
369	func (s *Store) worker() {
370		defer s.wg.Done()
371		for {
372			s.mu.Lock()
373			if s.stopping.Load() {
374				s.mu.Unlock()
375				return
376			}
377			j := s.pickRunnableLocked()
378			if j == nil {
379				ch := s.waitCh
380				s.mu.Unlock()
381				select {
382				case <-ch:
383				case <-s.stopCh:
384				}
385				continue
386			}
387	
388			// 进入运行并原子持久化该状态。
389			j.status = StatusRunning
390			j.startedAt = s.now().UTC()
391			inputs := append([]int64(nil), j.values...)
392			if j.hasDependency {
393				if dep := s.byID[j.dependencyID]; dep != nil && dep.archive != nil {
394					inputs = append(inputs, dep.archive.Sum)
395				}
396			}
397			seed := j.seed
398			s.runningID = j.id
399			if err := s.persistRetry(j, 3); err != nil {
400				// 连运行状态都无法落盘：保守地失败，不进行计算。
401				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
402				s.runningID = 0
403				s.cascadeLocked()
404				s.notifyLocked()
405				s.mu.Unlock()
406				continue
407			}
408			s.mu.Unlock()
409	
410			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
411			doCompute := s.compute
412			if doCompute == nil {
413				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
414					return computeResult(in, sd, c)
415				}
416			}
417			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
418	
419			s.mu.Lock()
420			s.runningID = 0
421			switch {
422			case j.status == StatusCanceled:
423				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
424				j.archive = nil
425				j.effectiveValues = nil
426				_ = s.persistRetry(j, 3)
427				s.cascadeLocked()
428			case s.stopping.Load():
429				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
430				s.cascadeLocked()
431			case !ok:
432				s.markFailedLocked(j, reason, 0)
433				s.cascadeLocked()
434			default:
435				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
436				completed := s.now().UTC()
437				a := newArchive(j, inputs, sum, sumSq, completed)
438				j.effectiveValues = append([]int64(nil), inputs...)
439				j.status = StatusSucceeded
440				j.finishedAt = completed
441				j.failureReason = ""
442				j.blockerID = 0
443				j.archive = a
444				if err := s.persistRetry(j, 3); err != nil {
445					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
446					j.archive = nil
447					j.effectiveValues = nil
448					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
449				}
450			}
451			s.notifyLocked()
452			s.mu.Unlock()
453		}
454	}
455	
456	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
457	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
458		j.status = StatusFailed
459		j.failureReason = reason
460		j.blockerID = blocker
461		if j.finishedAt.IsZero() {
462			j.finishedAt = s.now().UTC()
463		}
464		j.archive = nil
465		j.effectiveValues = nil
466		_ = s.persistRetry(j, 3)
467	}
468	
469	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
470	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
471		inDigest := inputsDigestHex(effective, j.seed)
472		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
473		log := buildLog(effective, j.seed, sum, sumSquares)
474		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
475		return &Archive{
476			JobID:           j.id,
477			Submitter:       j.submitter,
478			RequestID:       j.requestID,
479			Seed:            j.seed,
480			Values:          append([]int64(nil), j.values...),
481			HasDependency:   j.hasDependency,
482			DependencyID:    j.dependencyID,
483			EffectiveValues: append([]int64(nil), effective...),
484			InputsDigest:    inDigest,
485			Sum:             sum,
486			SumOfSquares:    sumSquares,
487			ResultDigest:    resDigest,
488			Log:             log,
489			Checksum:        checksum,
490			CompletedAt:     completedAt,
491		}
492	}
493	
494	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
495	func (s *Store) viewLocked(j *storedJob) *Job {
496		v := &Job{
497			ID:              j.id,
498			Submitter:       j.submitter,
499			RequestID:       j.requestID,
500			Seed:            j.seed,
501			Values:          append([]int64(nil), j.values...),
502			HasDependency:   j.hasDependency,
503			DependencyID:    j.dependencyID,
504			QueuedAt:        j.queuedAt,
505			StartedAt:       j.startedAt,
506			FinishedAt:      j.finishedAt,
507			Status:          j.status,
508			FailureReason:   j.failureReason,
509			BlockerID:       j.blockerID,
510			EffectiveValues: append([]int64(nil), j.effectiveValues...),
511		}
512		if j.status == StatusQueued {
513			v.WaitReason = WaitSlot
514			if j.hasDependency {
515				if dep := s.byID[j.dependencyID]; dep == nil || dep.status != StatusSucceeded {
516					v.WaitReason = WaitDependency
517				}
518			}
519		}
520		if j.archive != nil {
521			a := *j.archive
522			a.Values = append([]int64(nil), j.archive.Values...)
523			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
524			v.Archive = &a
525		}
526		return v
527	}
528	
529	// Dir 返回归档目录路径。
530	func (s *Store) Dir() string { return s.dir }
