1	package numeric
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync/atomic"
11		"time"
12	)
13	
14	// recordVersion 是落盘记录格式的版本标记。
15	const recordVersion = "numeric-job-v1"
16	
17	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
18	type storedJob struct {
19		id            uint64
20		submitter     string
21		requestID     string
22		seed          int64
23		values        []int64
24		hasDependency bool
25		dependencyID  uint64
26	
27		queuedAt   time.Time
28		startedAt  time.Time
29		finishedAt time.Time
30	
31		status        Status
32		failureReason string
33		blockerID     uint64
34	
35		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
36		effectiveValues []int64
37		archive         *Archive
38	
39		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
40		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
41		canceled atomic.Bool
42	}
43	
44	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
45	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
46	type jobRecord struct {
47		Version string `json:"version"`
48	
49		ID            uint64  `json:"id"`
50		Submitter     string  `json:"submitter"`
51		RequestID     string  `json:"request_id"`
52		Seed          int64   `json:"seed"`
53		Values        []int64 `json:"values"`
54		HasDependency bool    `json:"has_dependency"`
55		DependencyID  uint64  `json:"dependency_id"`
56	
57		QueuedAt   time.Time `json:"queued_at"`
58		StartedAt  time.Time `json:"started_at,omitempty"`
59		FinishedAt time.Time `json:"finished_at,omitempty"`
60	
61		Status        Status `json:"status"`
62		FailureReason string `json:"failure_reason,omitempty"`
63		BlockerID     uint64 `json:"blocker_id,omitempty"`
64	
65		EffectiveValues []int64  `json:"effective_values,omitempty"`
66		Archive         *Archive `json:"archive,omitempty"`
67	}
68	
69	func jobFileName(id uint64) string {
70		return fmt.Sprintf("job-%020d.json", id)
71	}
72	
73	func (s *Store) jobPath(j *storedJob) string {
74		return filepath.Join(s.dir, jobFileName(j.id))
75	}
76	
77	func encodeRecord(j *storedJob) ([]byte, error) {
78		r := jobRecord{
79			Version: recordVersion,
80	
81			ID:            j.id,
82			Submitter:     j.submitter,
83			RequestID:     j.requestID,
84			Seed:          j.seed,
85			Values:        append([]int64(nil), j.values...),
86			HasDependency: j.hasDependency,
87			DependencyID:  j.dependencyID,
88	
89			QueuedAt:      j.queuedAt,
90			StartedAt:     j.startedAt,
91			FinishedAt:    j.finishedAt,
92			Status:        j.status,
93			FailureReason: j.failureReason,
94			BlockerID:     j.blockerID,
95	
96			EffectiveValues: append([]int64(nil), j.effectiveValues...),
97			Archive:         j.archive,
98		}
99		return json.MarshalIndent(&r, "", "  ")
100	}
101	
102	// persist 在已持锁的情况下原子写一条作业记录。
103	func (s *Store) persist(j *storedJob) error {
104		data, err := encodeRecord(j)
105		if err != nil {
106			return err
107		}
108		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
109	}
110	
111	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
112	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
113	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
114		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
115		if err != nil {
116			return err
117		}
118		tmpName := tmp.Name()
119		cleanup := true
120		defer func() {
121			if cleanup {
122				_ = os.Remove(tmpName)
123			}
124		}()
125	
126		if _, err := tmp.Write(data); err != nil {
127			_ = tmp.Close()
128			return err
129		}
130		if err := tmp.Sync(); err != nil {
131			_ = tmp.Close()
132			return err
133		}
134		if err := tmp.Close(); err != nil {
135			return err
136		}
137		if err := os.Chmod(tmpName, perm); err != nil {
138			return err
139		}
140		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
141			return err
142		}
143		cleanup = false
144		syncDir(dir)
145		return nil
146	}
147	
148	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
149	func syncDir(dir string) {
150		if d, err := os.Open(dir); err == nil {
151			_ = d.Sync()
152			_ = d.Close()
153		}
154	}
155	
156	// loadDir 扫描目录中的全部作业记录并重建内存索引。
157	//
158	// 恢复规则：
159	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
160	//   - 成功记录缺少归档或校验值对不上时 fail-closed 地标记为失败，
161	//     维持“成功必有完整归档”的不变量。
162	func loadDir(dir string) ([]*storedJob, uint64, error) {
163		entries, err := os.ReadDir(dir)
164		if err != nil {
165			return nil, 0, err
166		}
167		var jobs []*storedJob
168		var maxID uint64
169		for _, e := range entries {
170			name := e.Name()
171			if e.IsDir() {
172				continue
173			}
174			// 清理上一进程崩溃时可能残留的原子写临时文件。
175			if strings.HasPrefix(name, ".tmp-") {
176				_ = os.Remove(filepath.Join(dir, name))
177				continue
178			}
179			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
180				continue
181			}
182			path := filepath.Join(dir, name)
183			data, err := os.ReadFile(path)
184			if err != nil {
185				return nil, 0, err
186			}
187			var r jobRecord
188			if err := json.Unmarshal(data, &r); err != nil {
189				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
190			}
191			if r.Version != recordVersion {
192				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
193			}
194			switch r.Status {
195			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
196			default:
197				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
198			}
199			j := &storedJob{
200				id:            r.ID,
201				submitter:     r.Submitter,
202				requestID:     r.RequestID,
203				seed:          r.Seed,
204				values:        append([]int64(nil), r.Values...),
205				hasDependency: r.HasDependency,
206				dependencyID:  r.DependencyID,
207	
208				queuedAt:   r.QueuedAt,
209				startedAt:  r.StartedAt,
210				finishedAt: r.FinishedAt,
211	
212				status:        r.Status,
213				failureReason: r.FailureReason,
214				blockerID:     r.BlockerID,
215	
216				effectiveValues: append([]int64(nil), r.EffectiveValues...),
217				archive:         r.Archive,
218			}
219			if j.status == StatusRunning {
220				j.status = StatusFailed
221				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
222				j.blockerID = 0
223				if j.finishedAt.IsZero() {
224					j.finishedAt = time.Now().UTC()
225				}
226				j.effectiveValues = nil
227				j.archive = nil
228				// 就地重写恢复后的终态。
229				if data, err := encodeRecord(j); err == nil {
230					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
231				}
232			}
233			if j.status == StatusSucceeded && !archiveIntact(j) {
234				j.status = StatusFailed
235				j.failureReason = "归档不完整或校验值不一致，成功结果不可用"
236				if j.finishedAt.IsZero() {
237					j.finishedAt = time.Now().UTC()
238				}
239				j.effectiveValues = nil
240				j.archive = nil
241				if data, err := encodeRecord(j); err == nil {
242					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
243				}
244			}
245			jobs = append(jobs, j)
246			if j.id > maxID {
247				maxID = j.id
248			}
249		}
250		sort.Slice(jobs, func(a, b int) bool {
251			if !jobs[a].queuedAt.Equal(jobs[b].queuedAt) {
252				return jobs[a].queuedAt.Before(jobs[b].queuedAt)
253			}
254			return jobs[a].id < jobs[b].id
255		})
256		return jobs, maxID, nil
257	}
258	
259	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
260	func archiveIntact(j *storedJob) bool {
261		a := j.archive
262		if a == nil {
263			return false
264		}
265		// 归档中的原始参数必须与记录顶层字段一致。
266		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
267			a.Seed != j.seed || a.HasDependency != j.hasDependency ||
268			(a.HasDependency && a.DependencyID != j.dependencyID) {
269			return false
270		}
271		if len(a.Values) != len(j.values) {
272			return false
273		}
274		for i := range j.values {
275			if a.Values[i] != j.values[i] {
276				return false
277			}
278		}
279		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
280			return false
281		}
282		for i := range j.effectiveValues {
283			if j.effectiveValues[i] != a.EffectiveValues[i] {
284				return false
285			}
286		}
287		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
288			return false
289		}
290		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
291			return false
292		}
293		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
294			return false
295		}
296		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
297			return false
298		}
299		return true
300	}
