608			t.Fatalf("cancel failed: %v", err)
609		}
610		got2, _ := s.Get(mm.ID)
611		if got2.Status != StatusFailed || got2.FailureReason != mm.FailureReason {
612			t.Fatal("failed record changed after rejected cancel")
613		}
614	}
