668			t.Fatalf("reason=%q archive=%v", failed.FailureReason, failed.Archive)
669		}
670	}
671	
672	func TestListBySubmitterAndTimeRange(t *testing.T) {
673		s, clock := openTestStore(t)
674		_ = clock
675		a1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
676		a2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{2}})
