func TestAddInt64(t *testing.T) {
	cases := []struct {
		a, b int64
		ok   bool
		want int64
	}{
		{1, 2, true, 3},
		{-1, -2, true, -3},
		{math.MaxInt64, 1, false, 0},
		{math.MinInt64, -1, false, 0},
		{math.MaxInt64, 0, true, math.MaxInt64},
		{math.MinInt64, 0, true, math.MinInt64},
		{math.MaxInt64, math.MinInt64, true, -1},
